/**
 * Build src/data/gen2DexWeights.ts: Gold/Silver/Crystal's own Pokédex weights.
 *
 * WHY A GENERATED FILE: Gen 2's Heavy Ball reads the weight from the game's
 * Pokédex entry -- in tenths of a POUND -- and converts it with integer shifts
 * (pokecrystal HeavyBallMultiplier). The bundle's weight is PokéAPI's
 * hectograms; converting back would round differently near the ball's
 * thresholds. So the catch calculator reads the game's own numbers, extracted
 * from the pinned disassembly (scripts/trainers/sources.mjs), not hand-typed.
 *
 * Index = national dex number (1-251). Throws if any species is missing.
 *
 * Usage: node scripts/build-catch-data.mjs
 */

import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { REPOS, ensureSources } from './trainers/sources.mjs'

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..')
const dirs = ensureSources(join(ROOT, '.cache/trainers'))
const P = join(dirs.pokecrystal, 'data/pokemon')

// PokedexDataPointerTable is in species order; each label names an INCLUDE.
const pointers = [
  ...readFileSync(join(P, 'dex_entry_pointers.asm'), 'utf8').matchAll(/^\s*dw\s+(\w+)/gm),
].map((m) => m[1])
const includes = new Map(
  [
    ...readFileSync(join(P, 'dex_entries.asm'), 'utf8').matchAll(
      /^(\w+)::\s*INCLUDE\s+"([^"]+)"/gm,
    ),
  ].map((m) => [m[1], m[2]]),
)
if (pointers.length !== 251) throw new Error(`expected 251 dex pointers, got ${pointers.length}`)

const weights = pointers.map((label, i) => {
  const file = includes.get(label)
  if (!file) throw new Error(`no INCLUDE for ${label} (species ${i + 1})`)
  const text = readFileSync(join(dirs.pokecrystal, file), 'utf8')
  const m = /dw\s+(\d+)\s*,\s*(\d+)\s*;\s*height,\s*weight/.exec(text)
  if (!m) throw new Error(`no "dw height, weight" line in ${file}`)
  return Number(m[2])
})

const out = `/**
 * GENERATED by scripts/build-catch-data.mjs -- do not edit by hand.
 *
 * Gold/Silver/Crystal Pokédex weights in tenths of a pound, by national dex
 * number (index 0 unused), from pret/pokecrystal @ ${REPOS.pokecrystal.sha.slice(0, 7)}
 * data/pokemon/dex_entries. Read by Gen 2's Heavy Ball (catchRateMath.ts).
 */
export const GEN2_DEX_WEIGHT_LB10: readonly number[] = [
  0,
${weights.map((w, i) => `  ${w}, // ${i + 1}`).join('\n')}
]
`
writeFileSync(join(ROOT, 'src/data/gen2DexWeights.ts'), out)
console.log(`wrote ${weights.length} weights (Snorlax #143: ${weights[142]})`)
